def secret(name):
    try:
        return st.secrets.get(name, os.getenv(name, ""))
    except Exception:
        return os.getenv(name, "")


def active_db_path(instrument_kind="USD_M_PERPETUAL"):
    """BUG-09: Return the isolated database path for the active instrument_kind."""
    if instrument_kind == "SPOT_REFERENCE":
        return paper_db_path(ROOT)
    if instrument_kind == "BYBIT_LINEAR_PERPETUAL":
        return bybit_db_path(ROOT)
    return futures_db_path(ROOT)


def stamp(ms):
    return datetime.fromtimestamp(ms / 1000, WIB).strftime("%d/%m/%Y %H:%M:%S WIB") if ms else "Belum scan"


def export_journal_authorized(ledger, security, session_token=None, fmt="json"):
    """BUG-10 & BUG-13: Server-side authorization and rate-limiting gate for journal exports."""
    allowed, reason = security.authorize_action("JOURNAL_EXPORT", session_token=session_token)
    if not allowed:
        return False, reason
    if fmt == "csv":
        rows = []
        for t in ledger.trades():
            p = t["plan"]
            rows.append({
                "Kategori Instrumen": t.get("market_category_label", p.get("instrument_kind", "USD_M_PERPETUAL")),
                "Pair": p["symbol"],
                "Jenis": LABELS[p["mode"]],
                "Arah": "BUY/LONG" if p["direction"] == "LONG" else "SELL/SHORT",
                "Sumber": p.get("instrument_kind", "USD_M_PERPETUAL"),
                "Status": t["status"],
                "Entry": p["entry"],
                "SL sekarang": t["stop"],
                "TP1": p["tp1"],
                "TP2": p["tp2"],
                "TP3": p.get("tp3", "-"),
                "Q rencana": p["qty"],
                "Q terbuka": t["remaining_qty"],
                "PnL bersih virtual": round(t["realized_pnl"], 6),
            })
        return True, pd.DataFrame(rows).to_csv(index=False).encode("utf-8-sig")
    return True, ledger.export_json()


def restore_journal_authorized(ledger, security, backup_payload, session_token=None):
    """BUG-17: Server-side authorized atomic restoration of a journal backup."""
    allowed, reason = security.authorize_action("JOURNAL_RESTORE", session_token=session_token)
    if not allowed:
        return False, reason
    try:
        res = ledger.import_backup_json(backup_payload)
        return True, f"Berhasil memulihkan {res['trades_restored']} trade pada jurnal {res.get('instrument_kind') or 'aktif'}."
    except Exception as exc:
        return False, f"Gagal memulihkan cadangan jurnal: {exc}"


UI_REFRESH_SECONDS = 60


def recover_state_after_restart(engine, force_latest=False):
    """BUG-13, BUG-18 & BUG-41: Recover latest persisted scan report from global `scanner_runs` and all ledgers."""
    current_rep = st.session_state.get("market_report")
    current_ts = int((current_rep or {}).get("completed_at_ms") or (current_rep or {}).get("started_at_ms") or (current_rep or {}).get("now_ms") or 0)
    if force_latest or not current_rep or not current_ts:
        candidates = []
        try:
            global_rep = load_latest_global_scan_run(
                getattr(engine, "_base_db", engine.ledger.db),
                pg_url=getattr(engine, "_pg_url", None),
                get_secret=getattr(engine, "_secret_getter", secret),
            )
            if isinstance(global_rep, dict) and (global_rep.get("started_at_ms") or global_rep.get("now_ms") or global_rep.get("scan_id")):
                candidates.append(global_rep)
        except Exception:
            pass
        seen_dbs = set()
        for lg in [engine.ledger] + [engine.ledger_for(k) for k in ("USD_M_PERPETUAL", "BYBIT_LINEAR_PERPETUAL", "SPOT_REFERENCE")]:
            if lg is None or str(lg.db) in seen_dbs:
                continue
            seen_dbs.add(str(lg.db))
            try:
                rep = lg.last_scan_report(global_latest=True) if hasattr(lg, "last_scan_report") else None
                if isinstance(rep, dict) and (rep.get("started_at_ms") or rep.get("now_ms") or rep.get("scan_id")):
                    candidates.append(rep)
            except Exception:
                continue
        if candidates:
            persisted = max(candidates, key=lambda r: int(r.get("completed_at_ms") or r.get("started_at_ms") or r.get("now_ms") or 0))
            persisted_ts = int(persisted.get("completed_at_ms") or persisted.get("started_at_ms") or persisted.get("now_ms") or 0)
            if persisted_ts >= current_ts:
                st.session_state["market_report"] = persisted
                if engine.last is None or int((engine.last or {}).get("started_at_ms") or 0) <= persisted_ts:
                    engine.last = persisted
                return True
    return False


def _cached_db_status(ledger, ttl_seconds=60.0):
    """Cache DB persistence & health probes for `ttl_seconds` so UI fragment reruns never saturate DB connections."""
    cache_key = f"_db_status_cache_{ledger.db}"
    now = time.monotonic()
    cached = st.session_state.get(cache_key)
    if cached and (now - cached["ts"]) < ttl_seconds:
        return cached["persistence"], cached["health"]
    db_info = ledger.persistence_info() if hasattr(ledger, "persistence_info") else persistence_status(ledger.db, secret, ledger=ledger)
    health_info = ledger.integrity_check() if hasattr(ledger, "integrity_check") else verify_database_health(ledger.db, get_secret=secret)
    st.session_state[cache_key] = {"ts": now, "persistence": db_info, "health": health_info}
    return db_info, health_info


@st.cache_resource(show_spinner=False)
def resources(signature, _keys, _token, _chat, _model, base_db, initial_equity, _admin_token="", _admin_hash="", _pg_url=""):
    # BUG-05, BUG-09, BUG-15, BUG-16, BUG-18, BUG-22, BUG-24, BUG-26:
    # Propagate centralized database config to all ledgers, security manager, and alerts.
    configure_database_runtime(secret_getter=secret, db_url=_pg_url)
    if getattr(SpotReferenceMarket.get, "__module__", "futures.spot_market") != "futures.spot_market":
        market = SpotReferenceMarket()
    else:
        market = FuturesProviderRouter()
    initial_kind = getattr(market, "instrument_kind", "USD_M_PERPETUAL")
    resolved_db = resolve_db_path(ROOT, initial_kind, base_db=base_db)
    verify_database_health(resolved_db, pg_url=_pg_url, get_secret=secret)
    security = SecurityManager(
        resolved_db,
        admin_token=_admin_token,
        admin_password_hash=_admin_hash,
        require_auth=True,
        pg_url=_pg_url,
        secret_getter=secret,
    )
    security.verify_public_deployment_startup(enforce_strict=False)
    pool = GroqRotation(_keys, security=security)
    calendar = NewsCalendar()
    ledger = PaperLedger(
        resolved_db,
        initial_equity,
        expected_instrument_kind=initial_kind,
        pg_url=_pg_url,
        secret_getter=secret,
    )
    alerts = TelegramAlerts(
        _token,
        _chat,
        resolved_db,
        security=security,
        pg_url=_pg_url,
        secret_getter=secret,
    )
    scanner = MarketScanner(
        market,
        pool,
        calendar,
        ledger,
        alerts,
        _model,
        security=security,
        trusted_worker=False,
    )
    for kind in ("USD_M_PERPETUAL", "BYBIT_LINEAR_PERPETUAL", "SPOT_REFERENCE"):
        scanner.ledger_for(kind)
    return scanner


def configuration():
    keys = []
    try:
        keys = load_keys(secret)
    except ValueError as exc:
        st.sidebar.error(str(exc))
    token, chat = secret("TELEGRAM_BOT_TOKEN"), secret("TELEGRAM_CHAT_ID")
    model = str(secret("GROQ_MODEL") or DEFAULT_MODEL)
    admin_token = str(secret("COINAGENT_ADMIN_TOKEN") or secret("ADMIN_TOKEN") or "")
    admin_hash = str(secret("COINAGENT_ADMIN_PASSWORD_HASH") or secret("ADMIN_PASSWORD_HASH") or "")
    user_id = str(secret("COINAGENT_USER_ID") or os.getenv("COINAGENT_USER_ID") or "global_operator").strip() or "global_operator"
    try:
        initial = float(secret("PAPER_INITIAL_EQUITY") or 1000)
    except (TypeError, ValueError):
        initial = 1000.0
    configure_database_runtime(secret_getter=secret)
    db_cfg = resolve_database_config(get_secret=secret)
    pg_url = db_cfg["pg_url"]
    auth_fp = compute_auth_config_fingerprint(admin_token, admin_hash, pg_url)
    base_db = futures_db_path(ROOT)
    global_ctrl_db = resolve_global_control_db_path(base_db)
    signature = hashlib.sha256(
        json.dumps([keys, str(token), str(chat), model, str(base_db), auth_fp, APP_VERSION, _EMBEDDED_BUNDLE_SHA256]).encode()
    ).hexdigest()
    engine = resources(signature, tuple(keys), token, chat, model, str(base_db), initial, admin_token, admin_hash, pg_url)

    # Support automated test authentication & query_params session persistence across browser reloads
    auto_auth_tok = st.session_state.pop("admin_auto_authenticate_token", None)
    if auto_auth_tok and not st.session_state.get("admin_session_token"):
        issued = engine.security.authenticate(auto_auth_tok)
        if issued:
            st.session_state["admin_session_token"] = issued

    if not st.session_state.get("admin_session_token"):
        try:
            qp_tok = st.query_params.get("session", "") if hasattr(st, "query_params") else ""
            if qp_tok:
                st.session_state["admin_session_token"] = str(qp_tok)
        except Exception:
            pass

    session_token = st.session_state.get("admin_session_token")
    session_info = engine.security.verify_session(session_token)
    if session_token and not session_info.get("authenticated"):
        st.session_state.pop("admin_session_token", None)
        try:
            if hasattr(st, "query_params") and "session" in st.query_params:
                del st.query_params["session"]
        except Exception:
            pass
        session_token = None
    is_admin = session_info["role"] == ROLE_ADMIN

    # BUG-38 & BUG-40: Load global `user_preferences` decoupled from trading ledgers.
    # Default risky automatic features (`auto_scan`, `relaxed_mode`, `send_alerts`, `send_watchlist_alerts`, `send_scan_summary`) to OFF (False).
    # Role changes (ADMIN <-> VIEWER) NEVER mutate or reset stored/displayed preference values!
    saved_prefs = load_global_preferences(global_ctrl_db, user_id=user_id, pg_url=pg_url, get_secret=secret)
    pref_defaults = {
        "cfg_auto": bool(saved_prefs.get("auto", DEFAULT_USER_PREFERENCES["auto"])),
        "cfg_relaxed": bool(saved_prefs.get("relaxed", DEFAULT_USER_PREFERENCES["relaxed"])),
        "cfg_interval": int(saved_prefs.get("interval", SCAN_INTERVALS[0])) if int(saved_prefs.get("interval", SCAN_INTERVALS[0])) in SCAN_INTERVALS else SCAN_INTERVALS[0],
        "cfg_candidates": int(saved_prefs.get("candidates", 2)) if int(saved_prefs.get("candidates", 2)) in (1, 2, 3, 5, 8, 10, 20, 50) else 2,
        "cfg_alert": bool(saved_prefs.get("alert", DEFAULT_USER_PREFERENCES["alert"])),
        "cfg_watchlist_alert": bool(saved_prefs.get("watchlist_alert", DEFAULT_USER_PREFERENCES["watchlist_alert"])),
        "cfg_summary_alert": bool(saved_prefs.get("summary_alert", DEFAULT_USER_PREFERENCES["summary_alert"])),
        "cfg_volume": float(saved_prefs.get("volume", 10_000_000.0)),
        "cfg_leverage": int(saved_prefs.get("leverage", 2)) if int(saved_prefs.get("leverage", 2)) in (1, 2, 3) else 2,
        "cfg_risk": float(saved_prefs.get("risk", 0.5)),
        "cfg_fee": float(saved_prefs.get("fee", 0.05)),
        "cfg_slip": float(saved_prefs.get("slip", 2.0)),
        "cfg_fund": float(saved_prefs.get("fund", 0.03)),
    }

    db_key = f"{global_ctrl_db}:{user_id}"
    db_updated_ms = int(saved_prefs.get("_updated_at_ms", 0))
    if st.session_state.get("_cfg_bound_db") != db_key:
        for k, val in pref_defaults.items():
            st.session_state[k] = val
        st.session_state["_cfg_bound_db"] = db_key
        st.session_state["_cfg_db_updated_ms"] = db_updated_ms
        st.session_state["_cfg_last_saved_dict"] = dict(pref_defaults)
        st.session_state["pref_save_status"] = "SAVED" if saved_prefs.get("_exists") else "DEFAULT_OFF"
        st.session_state["pref_save_error"] = ""
    else:
        for k, val in pref_defaults.items():
            if k not in st.session_state:
                st.session_state[k] = val

    cur_auto = bool(st.session_state.get("cfg_auto", pref_defaults["cfg_auto"]))
    cur_relaxed = bool(st.session_state.get("cfg_relaxed", pref_defaults["cfg_relaxed"]))
    cur_interval = st.session_state.get("cfg_interval", pref_defaults["cfg_interval"])
    if cur_interval not in SCAN_INTERVALS:
        cur_interval = SCAN_INTERVALS[0]
    cur_candidates = st.session_state.get("cfg_candidates", pref_defaults["cfg_candidates"])
    if cur_candidates not in (1, 2, 3, 5, 8, 10, 20, 50):
        cur_candidates = 2
    cur_alert = bool(st.session_state.get("cfg_alert", pref_defaults["cfg_alert"]))
    cur_wl_alert = bool(st.session_state.get("cfg_watchlist_alert", pref_defaults["cfg_watchlist_alert"]))
    cur_sum_alert = bool(st.session_state.get("cfg_summary_alert", pref_defaults["cfg_summary_alert"]))
    cur_vol = float(st.session_state.get("cfg_volume", pref_defaults["cfg_volume"]))
    cur_lev = int(st.session_state.get("cfg_leverage", pref_defaults["cfg_leverage"]))
    if cur_lev not in (1, 2, 3):
        cur_lev = 2
    cur_risk = float(st.session_state.get("cfg_risk", pref_defaults["cfg_risk"]))
    cur_fee = float(st.session_state.get("cfg_fee", pref_defaults["cfg_fee"]))
    cur_slip = float(st.session_state.get("cfg_slip", pref_defaults["cfg_slip"]))
    cur_fund = float(st.session_state.get("cfg_fund", pref_defaults["cfg_fund"]))

    with st.sidebar:
        st.subheader("Scanner otomatis")
        # BUG-38 #6 & #7: Role only restricts editing (`disabled=not is_admin`), NEVER alters toggle values!
        auto = st.toggle("Auto-scan seluruh market", value=cur_auto, key="cfg_auto", disabled=not is_admin)
        relaxed = st.toggle(
            "Adaptive Reversal & Medium-Liquidity Mode",
            value=cur_relaxed,
            key="cfg_relaxed",
            disabled=not is_admin,
            help="Mengaktifkan deteksi setup Reversal & Trend M15/M5 serta watchlist 5M USDT; validasi harga limit, depth, freshness (30s), dan kalender berita tetap ketat.",
        )
        interval = st.selectbox(
            "Interval scan (detik)",
            SCAN_INTERVALS,
            index=SCAN_INTERVALS.index(cur_interval),
            format_func=lambda x: SCAN_INTERVAL_LABELS.get(x, f"{x} detik"),
            key="cfg_interval",
            disabled=not is_admin,
        )
        candidates = st.selectbox(
            "Kandidat analisis mendalam",
            (1, 2, 3, 5, 8, 10, 20, 50),
            index=(1, 2, 3, 5, 8, 10, 20, 50).index(cur_candidates),
            key="cfg_candidates",
            disabled=not is_admin,
        )
        alert = st.toggle("Alert Telegram PAPER BUY/SELL", value=cur_alert, key="cfg_alert", disabled=not is_admin)
        watchlist_alert = st.toggle(
            "Alert Telegram REVERSAL WATCHLIST",
            value=cur_wl_alert,
            key="cfg_watchlist_alert",
            disabled=not is_admin,
            help="Kirim alert 👀 REVERSAL WATCHLIST jika kandidat memiliki skor M15 potensial tetapi masih menunggu konfirmasi entry M5.",
        )
        summary_alert = st.toggle(
            "Kirim MARKET SCANNER REPORT setiap siklus",
            value=cur_sum_alert,
            key="cfg_summary_alert",
            disabled=not is_admin,
            help="Mengirim laporan MARKET SCANNER REPORT ke Telegram pada setiap putaran scan (default OFF).",
        )

        current_ui_state = {
            "cfg_auto": bool(auto),
            "cfg_relaxed": bool(relaxed),
            "cfg_interval": int(interval),
            "cfg_candidates": int(candidates),
            "cfg_alert": bool(alert),
            "cfg_watchlist_alert": bool(watchlist_alert),
            "cfg_summary_alert": bool(summary_alert),
            "cfg_volume": float(cur_vol),
            "cfg_leverage": int(cur_lev),
            "cfg_risk": float(cur_risk),
            "cfg_fee": float(cur_fee),
            "cfg_slip": float(cur_slip),
            "cfg_fund": float(cur_fund),
        }

        st.caption("Alur Multi-Stage: Screen All Markets → Filter → Rank (0–100) → Top 1–2 → Deep Analysis → M5 Confirmation → Risk Validation → Telegram Alert.")
        with st.expander("Asumsi simulasi dan filter awal"):
            volume = st.number_input("Minimum volume 24 jam (USDT)", min_value=1_000_000., value=cur_vol, step=1_000_000., key="cfg_volume", disabled=not is_admin)
            leverage = st.select_slider("Leverage paper", options=[1, 2, 3], value=cur_lev, key="cfg_leverage", disabled=not is_admin)
            risk = st.number_input("Risiko per paper trade (%)", min_value=.05, max_value=.5, value=cur_risk, step=.05, key="cfg_risk", disabled=not is_admin)
            fee = st.number_input("Asumsi fee taker (%)", min_value=0., max_value=1., value=cur_fee, step=.01, format="%.4f", key="cfg_fee", disabled=not is_admin)
            slip = st.number_input("Cadangan slippage exit (bps)", min_value=0., value=cur_slip, step=.5, key="cfg_slip", disabled=not is_admin)
            fund = st.number_input("Cadangan biaya funding model (%)", min_value=0., value=cur_fund, step=.01, format="%.4f", key="cfg_fund", disabled=not is_admin)
            st.caption("SIMULASI PAPER: biaya model, bukan fee aktual akun. Cadangan funding dibebankan saat entry. Likuidasi bursa tidak dimodelkan.")

        current_ui_state.update({
            "cfg_volume": float(volume),
            "cfg_leverage": int(leverage),
            "cfg_risk": float(risk),
            "cfg_fee": float(fee),
            "cfg_slip": float(slip),
            "cfg_fund": float(fund),
        })

        # BUG-38 #4, #5, #9, #10: Transactional save on toggle/setting change with explicit SAVED / SAVE_FAILED indicator
        if is_admin and current_ui_state != st.session_state.get("_cfg_last_saved_dict"):
            save_res = save_global_preferences(
                global_ctrl_db,
                {
                    "auto": bool(auto),
                    "relaxed": bool(relaxed),
                    "strategy_profile": "BALANCED" if relaxed else "CONSERVATIVE",
                    "interval": int(interval),
                    "candidates": int(candidates),
                    "alert": bool(alert),
                    "watchlist_alert": bool(watchlist_alert),
                    "summary_alert": bool(summary_alert),
                    "volume": float(volume),
                    "leverage": int(leverage),
                    "risk": float(risk),
                    "fee": float(fee),
                    "slip": float(slip),
                    "fund": float(fund),
                },
                user_id=user_id,
                pg_url=pg_url,
                get_secret=secret,
            )
            st.session_state["pref_save_status"] = save_res.get("status", "SAVE_FAILED")
            st.session_state["pref_save_error"] = save_res.get("error", "")
            if save_res.get("ok"):
                st.session_state["_cfg_last_saved_dict"] = dict(current_ui_state)
                st.session_state["_cfg_db_updated_ms"] = int(save_res.get("updated_at_ms", 0))

        pref_status = st.session_state.get("pref_save_status", "SAVED")
        if pref_status == "SAVE_FAILED":
            st.error(f"Status Konfigurasi: SAVE_FAILED ({st.session_state.get('pref_save_error', 'Gagal menyimpan preferensi ke database')})")
        else:
            st.caption(f"Status Konfigurasi: SAVED · User ID: `{user_id}` (`user_preferences`)")

        with st.expander("Keamanan & Otorisasi Server-Side"):
            st.caption(f"Peran sesi aktif: {session_info['role']} · Status Admin Secret: {'Terkonfigurasi' if engine.security.admin_configured else 'Belum diatur (Mode Read-Only)'}")
            if not engine.security.admin_configured:
                st.caption("Tambahkan `COINAGENT_ADMIN_TOKEN` di Secrets untuk mengaktifkan login Administrator pada hosting publik.")
            unlock_prompt = st.checkbox("Masukkan token administrator", value=False, key="show_admin_login")
            if unlock_prompt:
                entered_token = st.text_input("Token Administrator", type="password", key="admin_token_input")
                if st.button("Verifikasi Admin", key="admin_login_btn"):
                    issued = engine.security.authenticate(entered_token)
                    if issued:
                        st.session_state["admin_session_token"] = issued
                        try:
                            if hasattr(st, "query_params"):
                                st.query_params["session"] = issued
                        except Exception:
                            pass
                        st.success("Autentikasi administrator berhasil.")
                        if hasattr(st, "rerun"):
                            st.rerun()
                    else:
                        st.error("Token administrator tidak valid.")
            if session_token and st.button("Logout Admin", key="admin_logout_btn"):
                engine.security.revoke_session(session_token)
                st.session_state.pop("admin_session_token", None)
                try:
                    if hasattr(st, "query_params") and "session" in st.query_params:
                        del st.query_params["session"]
                except Exception:
                    pass
                if hasattr(st, "rerun"):
                    st.rerun()
        st.divider()
        st.caption(f"Groq: {len(keys)}/7 key dari Secrets · {model}")
        st.caption("Telegram: " + ("terkonfigurasi dari Secrets" if engine.alerts.configured else "token/chat ID belum lengkap di Secrets"))
        if st.button("Kirim Tes Alert Telegram", key="test_telegram_btn",
                     help="Mengirim pesan uji coba langsung ke chat Telegram (khusus Administrator & dibatasi rate-limit server)."):
            ok, msg = engine.alerts.send_test_message(
                security=engine.security,
                session_token=st.session_state.get("admin_session_token"),
            )
            if ok:
                st.success(msg)
            else:
                st.error(msg)
        if not keys:
            st.info("Tambahkan GROQ_API_KEY di Secrets untuk mengaktifkan catatan kontekstual AI (Advisor-Only); Rule Engine (Strategy F) tetap mengevaluasi dan memvalidasi sinyal secara independen walaupun AI tidak tersedia.")
        with st.expander("Status Groq"):
            st.dataframe(pd.DataFrame(engine.pool.status()), hide_index=True)
        st.caption("Untuk pemantauan 24/7 independen dari sesi browser, jalankan `worker.py` di server persisten dengan `DATABASE_URL` (PostgreSQL/Supabase).")

    # BUG-38 & BUG-40: ScannerConfig reflects the global `user_preferences` identically for ADMIN, VIEWER, and Worker!
    eff_ui_profile = "BALANCED" if relaxed else str(saved_prefs.get("strategy_profile", "BALANCED")).strip().upper()
    if eff_ui_profile not in ("CONSERVATIVE", "BALANCED", "ACTIVE"):
        eff_ui_profile = "BALANCED"
    config = ScannerConfig(
        candidates=int(candidates),
        min_volume=float(volume),
        fee=float(fee) / 100.0,
        slippage_bps=float(slip),
        funding=float(fund) / 100.0,
        leverage=int(leverage),
        risk_pct=float(risk),
        send_alerts=bool(alert),
        send_watchlist_alerts=bool(watchlist_alert),
        send_scan_summary=bool(summary_alert),
        relaxed_mode=bool(relaxed or eff_ui_profile in ("BALANCED", "ACTIVE")),
        strategy_profile=eff_ui_profile,
        strategy_engine="HYBRID_ADAPTIVE_V1",
        allow_paper_on_ai_unavailable=True,
        advisor_only_ai=True,
        futures_primary_only=True,
        interval=int(interval),
    )
    return engine, config, bool(auto)


def freshness(report, configured_interval=60, effective_interval=60):
    started = report.get("last_scan_at_ms") or report.get("started_at_ms") or report.get("now_ms", 0)
    if not started:
        st.caption("Belum ada percobaan scan.")
        return
    status = {
        "RUNNING": "Sedang berjalan",
        "FAILED": "Gagal mengambil/memproses data",
        "PARTIAL_SCAN": "Sebagian kandidat selesai (PARTIAL_SCAN — sisanya diantrekan)",
        "COMPLETED": "Selesai",
        "COMPLETED_WITH_NOTES": "Selesai dengan catatan",
    }.get(report.get("scan_status"), "Selesai")
    data_status = report.get("data_status", "OK")
    next_scan_ms = int(report.get("next_scan_at_ms") or (started + int(effective_interval) * 1000))
    st.caption(
        f"Percobaan scan terakhir: {stamp(started)} · Jadwal scan berikutnya: {stamp(next_scan_ms)} · "
        f"{status} · Status data: {data_status} · durasi {report.get('duration_seconds', 0):.2f} detik · "
        f"Interval konfigurasi: {configured_interval}s · Interval efektif: {effective_interval}s"
    )
    if report.get("scan_id"):
        st.caption(f"ID scan: {report['scan_id']} · pemicu: {report.get('trigger', 'AUTO')} · sumber: {report.get('market_provider', report.get('instrument_kind', 'USD_M_PERPETUAL'))}")
    if not report.get("now_ms"):
        st.info("Belum ada data pasar yang berhasil diambil pada percobaan ini.")
        return
    if report.get("universe_loaded") is False:
        st.info("Waktu bursa diterima, tetapi data seluruh market belum berhasil dimuat.")
        return
    captured = report.get("display_monotonic")
    age = report.get("display_server_age", 0) + time.monotonic() - captured if captured is not None else (time.time() * 1000 - report.get("now_ms", 0)) / 1000
    st.caption(f"Waktu data pasar: {stamp(report['now_ms'])}")
    if age > 30:
        st.info("Snapshot hasil scan sudah lebih dari 30 detik. Tunggu scan baru; tabel ini merupakan catatan analisis.")


def paper_table(engine, now_ms):
    active_kind = getattr(engine.market, "instrument_kind", "USD_M_PERPETUAL")
    ledger = engine.ledger_for(active_kind)
    val_meta = spot_reference_validation_metadata(active_kind)
    db_info, _ = _cached_db_status(ledger)
    if db_info.get("backend") == "POSTGRESQL_ERROR":
        st.error(db_info.get("detail", "Konfigurasi PostgreSQL gagal."))
    s = ledger.summary(now_ms)
    cols = st.columns(4)
    for col, label, value in zip(cols, ["Ekuitas virtual (SIMULASI)", "PnL terealisasi (SIMULASI)", "PnL mengambang (SIMULASI)", "Posisi + pending"],
                                [f"{s['equity']:,.2f} USDT", f"{s['realized']:,.2f} USDT", f"{s['unrealized']:,.2f} USDT", f"{s['active']}/2"]):
        col.metric(label, value)
    persist_label = "PERSISTENT" if db_info.get("persistent") else "NON-PERSISTENT (Lokal)"
    st.caption(
        f"Jurnal Aktif: {val_meta['market_category_label']} · DB: {ledger.db.name} · "
        f"Backend: {db_info['backend']} ({persist_label}). "
        "Jurnal Spot Reference, Bybit Perpetual, dan Binance USD-M Futures dipisahkan pada database berbeda dengan saldo virtual independen."
    )
    if val_meta["is_spot_reference"]:
        st.caption(
            "ℹ️ CATATAN SPOT REFERENCE (BUKAN FUTURES PERPETUAL): "
            f"{val_meta['mark_price_claim']} {val_meta['funding_claim']} {val_meta['leverage_claim']} {val_meta['pnl_claim']}"
        )
    trades = ledger.trades()
    rows = []
    for t in trades:
        p = t["plan"]
        kind = p.get("instrument_kind", "USD_M_PERPETUAL")
        rows.append({
            "Kategori": "SPOT SIMULASI (Non-Perpetual)" if kind == "SPOT_REFERENCE" else f"PERPETUAL SIMULASI ({kind})",
            "Pair": p["symbol"],
            "Strategi": p.get("strategy", t.get("strategy_id", "F")),
            "Regime M15": p.get("m15_regime", t.get("m15_regime", "-")),
            "Jenis": LABELS[p["mode"]],
            "Arah": "BUY/LONG" if p["direction"] == "LONG" else "SELL/SHORT",
            "Setup Quality Score": p.get("setup_quality_score", p.get("confidence_score", 90)),
            "Leverage (Simulasi)": f"{p['leverage']}x",
            "Sumber": kind,
            "Status": t["status"],
            "Entry": p["entry"],
            "SL sekarang": t["stop"],
            "TP1 (+1R 40%)": p["tp1"],
            "TP2 (+2R 35%)": p["tp2"],
            "TP3 (+3R 25%)": p.get("tp3", "-"),
            "Q rencana": p["qty"],
            "Q terbuka": t["remaining_qty"],
            "PnL bersih virtual": round(t["realized_pnl"], 6),
            "Fill virtual": stamp(p.get("fill_ms")),
            "TP1 terisi": bool(t["tp1_ms"]),
            "TP2 terisi": bool(t["tp2_ms"]),
            "TP3 terisi": bool(t.get("tp3_ms")),
            "Waktu": stamp(t["updated_ms"]),
            "Kualitas": t["quality"],
            "Catatan": t["note"],
            "Telegram": t["telegram"],
        })
    session_token = st.session_state.get("admin_session_token")
    session_info = engine.security.verify_session(session_token)
    if rows:
        frame = pd.DataFrame(rows)
        st.dataframe(frame, hide_index=True, use_container_width=True)
        if session_info["role"] == ROLE_ADMIN:
            st.download_button("Unduh jurnal CSV", frame.to_csv(index=False).encode("utf-8-sig"), f"paper_trades_{active_kind.lower()}.csv", "text/csv")
    else:
        st.info("Belum ada sinyal PAPER yang lolos pada jurnal instrumen ini. WAIT/NO TRADE tidak membuka trade.")
    if session_info["role"] == ROLE_ADMIN:
        st.download_button("Unduh cadangan jurnal lengkap", ledger.export_json(), f"paper_trading_backup_{active_kind.lower()}.json", "application/json")
        with st.expander("Pemulihan Jurnal dari Cadangan JSON (Khusus Administrator)"):
            st.caption("Gunakan fitur ini untuk memulihkan saldo, posisi aktif/pending, riwayat trade, dan deduplikasi Telegram secara atomik setelah redeploy.")
            restore_confirm = st.checkbox("Saya mengonfirmasi pemulihan cadangan jurnal ke database aktif", value=False, key="confirm_restore_chk")
            if restore_confirm:
                backup_text = st.text_input("Tempel JSON cadangan jurnal", value="", key="restore_json_input")
                if st.button("Pulihkan Jurnal Sekarang", key="restore_json_btn") and backup_text.strip():
                    ok_rest, msg_rest = restore_journal_authorized(ledger, engine.security, backup_text, session_token=session_token)
                    if ok_rest:
                        st.success(msg_rest)
                    else:
                        st.error(msg_rest)
    else:
        st.caption("Ekspor dan pemulihan cadangan jurnal dibatasi untuk Administrator.")
    if hasattr(ledger, "performance_metrics"):
        perf = ledger.performance_metrics()
        with st.expander("Statistik Kinerja PAPER & Kalibrasi Out-of-Sample (Win Rate, Expectancy, Profit Factor, Drawdown)"):
            st.caption(perf.get("disclaimer", "Skor confidence adalah kualitas konfluensi teknikal (0–100), bukan win probability."))
            st.dataframe(pd.DataFrame([{
                "Total Sinyal": perf["total_signals"],
                "Trade Selesai": perf["closed_trades"],
                "Win Rate (%)": f"{perf['win_rate_pct']:.2f}%",
                "Expectancy (USDT)": f"{perf['expectancy_usdt']:+.4f}",
                "Expectancy (R)": f"{perf['expectancy_r']:+.3f}R",
                "Profit Factor": f"{perf['profit_factor']:.2f}",
                "Max Drawdown (%)": f"{perf['max_drawdown_pct']:.2f}%",
                "Status Kalibrasi": "CALIBRATED" if perf["calibrated"] else "UNCALIBRATED",
            }]), hide_index=True, use_container_width=True)
    with st.expander("Ringkasan Lintas-Ledger (Futures USD-M vs Bybit Perpetual vs Spot Reference)"):
        summary_rows = []
        for kind_key in ("USD_M_PERPETUAL", "BYBIT_LINEAR_PERPETUAL", "SPOT_REFERENCE"):
            lg = engine.ledger_for(kind_key)
            sm = lg.summary(now_ms)
            summary_rows.append({
                "Instrumen": kind_key,
                "Database": database_display_identity(lg.db, pg_url=getattr(lg, "pg_url", None), get_secret=getattr(lg, "secret_getter", None)),
                "Ekuitas Virtual (USDT)": round(sm["equity"], 2),
                "PnL Terealisasi (USDT)": round(sm["realized"], 4),
                "Posisi Aktif/Pending": sm["active"],
                "Total Trade": len(lg.trades()),
            })
        st.dataframe(pd.DataFrame(summary_rows), hide_index=True, use_container_width=True)
    st.caption("Tabel/CSV memuat 500 trade terbaru. Cadangan JSON memuat seluruh trade dan peristiwa jurnal.")
    st.caption("PENDING belum dianggap fill. Fill memakai quote Bid/Ask dan kedalaman order book yang diamati; tidak menyimpulkan fill dari sentuhan candle.")
    st.caption("Gap data (>3 menit): pending dibatalkan sebagai DATA_GAP; posisi terbuka ditutup pada quote baru sebagai DATA_GAP_EXIT tanpa mengarang keuntungan/kerugian fiktif.")


def dashboard(engine, config, auto):
    GLOBAL_MONITOR.increment("dashboard_refreshes")
    session_token = st.session_state.get("admin_session_token")
    session_info = engine.security.verify_session(session_token)
    is_admin = session_info["role"] == ROLE_ADMIN

    # BUG-41: Always synchronize latest report from global `scanner_runs` across all providers first
    recover_state_after_restart(engine, force_latest=True)

    hb = engine.ledger.worker_heartbeat() if hasattr(engine.ledger, "worker_heartbeat") else None
    worker_health = engine.ledger.worker_health_status() if hasattr(engine.ledger, "worker_health_status") else {"status": "NO_WORKER", "worker_state": "WORKER_OFFLINE", "alive": bool(hb)}
    worker_alive = bool(worker_health.get("alive"))

    manual_clicked = st.button("Scan sekarang", type="primary", key="market_scan_now",
                               help="Memulai percobaan baru tanpa menunggu interval (khusus Administrator & dibatasi frekuensi).")
    schedule = st.session_state.setdefault("market_schedule", ScanSchedule())
    context = json.dumps(asdict(config), sort_keys=True)
    previous_report = st.session_state.get("market_report") or engine.last or {}
    if engine.last and int(engine.last.get("started_at_ms", 0)) > int(previous_report.get("started_at_ms", 0)):
        previous_report = engine.last
        st.session_state["market_report"] = previous_report

    manual = False
    if manual_clicked:
        if not is_admin:
            _, reason = engine.security.authorize_action("MANUAL_SCAN", session_token=session_token)
            st.warning(reason)
        else:
            manual = True

    paused = previous_report.get("market_error", {}).get("access_blocked", False)
    # BUG-36 & BUG-37:
    # 1. If an independent 24/7 Worker is alive (`worker_alive=True`), prevent two schedulers from running scans simultaneously:
    #    the dashboard only reads from `scanner_runs` unless Admin explicitly clicks manual "Scan sekarang".
    # 2. If no external Worker is alive (`WORKER_OFFLINE`, e.g. on Streamlit Cloud), scheduled auto-scan runs via
    #    the internal ROLE_WORKER service session (`issue_worker_session()`), decoupled from ADMIN login token expiry!
    # 3. On production Streamlit Cloud (`not is_test_environment()`), if no scan report exists yet in `scanner_runs`,
    #    run an initial market scan automatically so the user immediately sees market results.
    need_initial_prod_scan = bool(
        not is_test_environment()
        and not worker_alive
        and not paused
        and not previous_report.get("universe_loaded")
        and not st.session_state.get("_initial_prod_scan_done")
    )
    allow_embedded_worker_auto = bool((auto or need_initial_prod_scan) and not worker_alive)
    if ((manual and is_admin) or (allow_embedded_worker_auto and not paused)) and schedule.claim(
        time.monotonic(), allow_embedded_worker_auto, config.interval, context, manual or need_initial_prod_scan
    ):
        if need_initial_prod_scan:
            st.session_state["_initial_prod_scan_done"] = True
        scan_token = session_token if (manual or is_admin) else engine.security.issue_worker_session()
        try:
            with st.spinner("Memantau paper trade, menyaring seluruh market (Multi-Stage), lalu menganalisis kandidat..."):
                previous = engine.last
                run_params = inspect.signature(engine.run).parameters
                if "session_token" in run_params:
                    report = engine.run(config, manual=manual, session_token=scan_token)
                else:
                    report = engine.run(config, manual=manual)
                if report.get("auth_error"):
                    st.warning(report["auth_error"])
                else:
                    if report is not previous and report.get("now_ms"):
                        report["display_monotonic"] = time.monotonic()
                        report["display_server_age"] = max(0, (time.time() * 1000 - report.get("now_ms", 0)) / 1000)
                    st.session_state["market_report"] = report
        except Exception as exc:
            st.error("WAIT · siklus belum selesai: " + engine.pool.redact(str(exc))[:250])
        finally:
            schedule.finish(time.monotonic(), config.interval)
    else:
        recover_state_after_restart(engine, force_latest=True)

    report = st.session_state.get("market_report") or engine.last or {}
    paused = report.get("market_error", {}).get("access_blocked", False)
    if report.get("scan_notice"):
        st.info(report["scan_notice"])
    if report.get("provider_failover"):
        st.info("Failover Sumber Data Aktif: " + str(report["provider_failover"]))
    if report.get("summary_telegram"):
        st.caption("Telegram Ringkasan: " + str(report["summary_telegram"]))
    scanner_tab, paper_tab, history_tab, rules_tab = st.tabs(["Scanner market", "Paper trading", "Riwayat analisis", "Aturan"])
    with scanner_tab:
        active_kind = report.get("instrument_kind") or getattr(engine.market, "instrument_kind", "USD_M_PERPETUAL")
        val_meta = spot_reference_validation_metadata(active_kind)
        configured_interval = int(config.interval)
        effective_interval = int(worker_health.get("interval_seconds") or report.get("effective_interval") or configured_interval) if worker_alive else int(report.get("effective_interval") or configured_interval)
        worker_state_badge = "WORKER_ONLINE" if worker_alive else "WORKER_OFFLINE"
        eff_worker_profile = str(
            worker_health.get("effective_strategy_profile")
            or (hb or {}).get("effective_strategy_profile")
            or report.get("effective_strategy_profile")
            or report.get("strategy_profile")
            or getattr(config, "strategy_profile", "BALANCED")
        )
        st.write("**SCREEN ALL MARKETS → FILTER → M15 REGIME & RANK (50 PIPELINE) → M5 TRIGGER ROUTING (STRATEGY A–E / F · TARGET 20) → HARD RISK GATES → ADVISOR AI (TOP 5) → PAPER & TELEGRAM ALERT**")
        v11_worker_st = worker_health.get("v11_status") or ("ONLINE" if worker_alive else ("NO_WORKER" if not hb else "OFFLINE"))
        eff_worker_eng = str(worker_health.get("effective_strategy_engine") or (hb or {}).get("effective_strategy_engine") or "HYBRID_ADAPTIVE_V1")
        hb_db_name = str(worker_health.get("database_name") or engine.ledger_for(active_kind).db.name)
        hb_text = (
            f" · Status Worker: **{worker_state_badge}** (`{v11_worker_st}` · `{hb['worker_id']}` · Heartbeat: {stamp(hb['heartbeat_ms'])} · Last Scan: {stamp(hb.get('last_scan_ms'))} · Next Scan: {stamp(hb.get('next_scan_ms'))} · Effective Profile: **{eff_worker_profile}** · Engine: **{eff_worker_eng}** · DB: `{hb_db_name}`)"
            if hb else f" · Status Worker: **{worker_state_badge}** (`{v11_worker_st}` · Worker 24/7 belum aktif · Effective Profile: **{eff_worker_profile}** · Engine: **{eff_worker_eng}** · DB: `{hb_db_name}`)"
        )
        st.caption(f"Kategori Sumber Aktif: **{val_meta['market_category_label']}** · Engine Produksi: **Strategy F (HYBRID_ADAPTIVE_V1.1)** · Effective Strategy Profile: **{eff_worker_profile}** · Database Jurnal: `{engine.ledger_for(active_kind).db.name}`{hb_text}")
        if report.get("data_status") == "FUTURES_DATA_UNAVAILABLE" or getattr(engine.market, "futures_data_unavailable", False):
            st.warning("⚠️ FUTURES_DATA_UNAVAILABLE: Tidak ada provider Futures Perpetual yang tersedia (Binance USDⓈ-M & Bybit Linear gagal/diblokir). Sistem menahan seluruh PAPER_ENTRY Futures.")
        if not worker_alive:
            st.caption(f"⚠️ Status Worker Independen: **WORKER_OFFLINE** — {worker_health.get('detail', 'Jalankan worker.py untuk pemindaian 24/7 independen dari sesi login Admin.')}")
        if worker_health.get("status") in ("WORKER_DEAD_OR_DISCONNECTED", "DB_CONNECTION_LOST"):
            st.warning(worker_health.get("detail", "WORKER_OFFLINE: Worker 24/7 tidak merespons."))
        if val_meta["is_spot_reference"]:
            st.caption(
                "ℹ️ MODE SPOT REFERENCE (SIMULASI NON-PERPETUAL): Harga Last Spot tidak identik dengan Mark Price Futures; "
                "funding dan leverage hanya asumsi simulasi; perhitungan PnL tidak disamakan dengan kontrak perpetual."
            )
        try:
            from futures.predictive_ui import render_predictive_watchlist_tab
            from futures.predictive_store import PredictiveSignalRepository
            _pw_repo = getattr(engine, "predictive_store", None) or PredictiveSignalRepository(
                engine.ledger_for(active_kind).db,
                pg_url=getattr(engine.ledger_for(active_kind), "pg_url", None),
                secret_getter=getattr(engine.ledger_for(active_kind), "secret_getter", None),
            )
            with st.expander("📡 Predictive Watchlist v1.0 (M1/M5/M15 Early Detection — PRE-WATCH / EARLY WATCH / SETUP FORMING / CONFIRMED)", expanded=True):
                render_predictive_watchlist_tab(
                    st,
                    _pw_repo,
                    worker_status={
                        "alive": worker_alive,
                        "worker_id": (hb or {}).get("worker_id", "-"),
                        "active_provider": report.get("market_provider", getattr(engine.market, "market_label", "-")),
                        "database_fingerprint": _pw_repo.database_identity().get("database_fingerprint", "-"),
                    },
                )
        except Exception as _pw_exc:
            st.caption(f"Predictive Watchlist tidak tersedia sementara: {_pw_exc}")
        cols = st.columns(4)
        for col, label, value in zip(cols, ["Market aktif", "Lolos filter awal", "Shortlist", "Kandidat mendalam"],
                                    ([report.get("universe_count", 0), report.get("eligible_count", 0), len(report.get("shortlist", [])), len(report.get("selected", []))]
                                     if report and report.get("universe_loaded") is not False else ["N/A"] * 4)):
            col.metric(label, value)
        if report:
            freshness(report, configured_interval=configured_interval, effective_interval=effective_interval)
        eff_interval_label = SCAN_INTERVAL_LABELS.get(effective_interval, f"{effective_interval} detik")
        mode_tag = "MEDIUM LIQUIDITY WATCHLIST" if getattr(config, "relaxed_mode", False) else "STRICT ENTRY GATES"
        auto_label = "DIJEDA (HTTP 451)" if auto and paused else (f"ON / {eff_interval_label} ({mode_tag})" if auto else f"OFF ({mode_tag})")
        st.caption("Sesi aktif · auto-scan " + auto_label + f" · Refresh UI pasif: {UI_REFRESH_SECONDS}s. Jadwal melambat jika API lambat; tidak ada penumpukan scan.")
        if paused:
            st.error("Akses data Binance ditolak (HTTP 451). Percobaan scan telah dijalankan, tetapi server belum memperoleh data yang diperlukan.")
            st.info("Permintaan berasal dari server tempat Streamlit berjalan. Periksa kelayakan akses wilayah/IP server "
                    "dengan penyedia data atau hosting. Setelah akses diperbaiki, klik Scan sekarang.")
        for message in report.get("errors", [])[:8]:
            st.warning(message)

        # BUG-39: Explicit Filter Rejection Breakdown & Summary Diagnostics
        if report and report.get("universe_loaded"):
            rej_bd = report.get("rejection_breakdown") or (report.get("filter_diagnostics") or {}).get("rejection_breakdown") or {}
            with st.expander("Diagnostik Filter Market & Breakdown Penolakan (BUG-39)"):
                st.caption(
                    f"Total market ditemukan: **{report.get('total_discovered', report.get('universe_count', 0))}** · "
                    f"Total valid: **{report.get('eligible_count', 0)}** · "
                    f"Total ditolak: **{report.get('rejected_count', 0)}** · "
                    f"Total shortlist: **{report.get('shortlist_count', len(report.get('shortlist', [])))}** · "
                    f"Total kandidat dianalisis: **{report.get('analyzed_count', len(report.get('analyses', [])))}**"
                )
                rej_rows = [
                    {"Kategori Penolakan Filter": "Volume 24h rendah (< batas minimum)", "Kode": "rejected_low_volume", "Jumlah Pair": int(rej_bd.get("rejected_low_volume", 0))},
                    {"Kategori Penolakan Filter": "Spread bid/ask terlalu lebar (> 10 bps)", "Kode": "rejected_wide_spread", "Jumlah Pair": int(rej_bd.get("rejected_wide_spread", 0))},
                    {"Kategori Penolakan Filter": "Jumlah transaksi 24h kurang (< 1.000)", "Kode": "rejected_low_trades", "Jumlah Pair": int(rej_bd.get("rejected_low_trades", 0))},
                    {"Kategori Penolakan Filter": "Quote orderbook/ticker kedaluwarsa (> 60s)", "Kode": "rejected_stale_quote", "Jumlah Pair": int(rej_bd.get("rejected_stale_quote", 0))},
                    {"Kategori Penolakan Filter": "Data candle / orderbook tidak tersedia", "Kode": "rejected_missing_candle", "Jumlah Pair": int(rej_bd.get("rejected_missing_candle", 0))},
                    {"Kategori Penolakan Filter": "Simbol tidak aktif / non-USDT / non-perpetual", "Kode": "rejected_invalid_symbol", "Jumlah Pair": int(rej_bd.get("rejected_invalid_symbol", 0))},
                    {"Kategori Penolakan Filter": "Rentang intraday di luar batas (0.5%–30%)", "Kode": "rejected_intraday_range", "Jumlah Pair": int(rej_bd.get("rejected_intraday_range", 0))},
                ]
                st.dataframe(pd.DataFrame(rej_rows), hide_index=True, use_container_width=True)

        if report and isinstance(report.get("diagnostic_panel"), dict):
            dp = report["diagnostic_panel"]
            with st.expander("Panel Diagnostik Wajib (19 Metrik Funnel & Alasan Penolakan — BUG-45..53)", expanded=False):
                st.caption(f"ID Scan: `{report.get('scan_id', '-')}` · Profil Strategi: **{report.get('strategy_profile', getattr(config, 'strategy_profile', 'CONSERVATIVE'))}** · Antrean Rotasi: `{len(report.get('rotating_queue', []))} pair`")
                panel_rows = [
                    {"Metrik Funnel": "Universe total", "Nilai": dp.get("universe_total", 0)},
                    {"Metrik Funnel": "Lolos liquidity", "Nilai": dp.get("lolos_liquidity", 0)},
                    {"Metrik Funnel": "Lolos spread", "Nilai": dp.get("lolos_spread", 0)},
                    {"Metrik Funnel": "Lolos freshness", "Nilai": dp.get("lolos_freshness", 0)},
                    {"Metrik Funnel": "Lolos candle history", "Nilai": dp.get("lolos_candle_history", 0)},
                    {"Metrik Funnel": "M15 watch (≥55)", "Nilai": dp.get("m15_watch", 0)},
                    {"Metrik Funnel": "M15 priority (≥70)", "Nilai": dp.get("m15_priority", 0)},
                    {"Metrik Funnel": "M5 analyzed", "Nilai": dp.get("m5_analyzed", 0)},
                    {"Metrik Funnel": "Rule-based valid", "Nilai": dp.get("rule_based_valid", 0)},
                    {"Metrik Funnel": "AI confirmed", "Nilai": dp.get("ai_confirmed", 0)},
                    {"Metrik Funnel": "AI unavailable", "Nilai": dp.get("ai_unavailable", 0)},
                    {"Metrik Funnel": "Rejected by confidence", "Nilai": dp.get("rejected_by_confidence", 0)},
                    {"Metrik Funnel": "Rejected by news", "Nilai": dp.get("rejected_by_news", 0)},
                    {"Metrik Funnel": "Rejected by cost", "Nilai": dp.get("rejected_by_cost", 0)},
                    {"Metrik Funnel": "Rejected by risk", "Nilai": dp.get("rejected_by_risk", 0)},
                    {"Metrik Funnel": "Rejected by position limit", "Nilai": dp.get("rejected_by_position_limit", 0)},
                    {"Metrik Funnel": "Telegram sent", "Nilai": dp.get("telegram_sent", 0)},
                    {"Metrik Funnel": "Telegram blocked", "Nilai": dp.get("telegram_blocked", 0)},
                    {"Metrik Funnel": "Last scan error", "Nilai": str(dp.get("last_scan_error") or "-")},
                ]
                st.dataframe(pd.DataFrame(panel_rows), hide_index=True, use_container_width=True)

        if report and isinstance(report.get("scanner_diagnostics"), dict):
            sd = report["scanner_diagnostics"]
            with st.expander("Diagnostik Scanner Wajib P0 (Regime M15, Kandidat A–E, Trigger M5, Hard Gates, Groq Advisor & Heartbeat)", expanded=False):
                st.caption(
                    f"Universe: **{sd.get('universe_total', 0)}** · Lolos Stage 1: **{sd.get('lolos_stage_1', 0)}** · "
                    f"Lolos Candle History (≥250): **{sd.get('lolos_candle_history', 0)}** · "
                    f"Gagal Candle History (HISTORY_INSUFFICIENT): **{sd.get('rejected_by_candle_history', 0)}** · "
                    f"Trigger M5 Aktif: **{sd.get('m5_trigger_count', 0)}**"
                )
                st.json({
                    "pipeline_reconciliation": report.get("pipeline_diagnostics") or sd.get("pipeline_reconciliation", {}),
                    "m15_regime_distribution": sd.get("m15_regime_distribution", {}),
                    "strategy_candidate_counts": sd.get("strategy_candidate_counts", {}),
                    "m5_trigger_count": sd.get("m5_trigger_count", 0),
                    "setup_quality_scores": sd.get("setup_quality_scores", []),
                    "hard_gate_rejection_reasons": sd.get("hard_gate_rejection_reasons", {}),
                    "groq_status_counts": sd.get("groq_status_counts", {}),
                    "telegram_status_counts": sd.get("telegram_status_counts", {}),
                    "queue_age_ms": sd.get("queue_age_ms", []),
                    "candidate_processing_latency_ms": sd.get("candidate_processing_latency_ms", []),
                    "provider_failover": sd.get("provider_failover", report.get("provider_failover", "")),
                    "worker_heartbeat": sd.get("worker_heartbeat", {}),
                    "persistence_status": sd.get("persistence_status", {}),
                    "budget_telemetry": sd.get("budget_telemetry", {}),
                    "predictive_watchlist": sd.get("predictive_watchlist", {}),
                    "market_stream": sd.get("market_stream", {}),
                    "database": sd.get("database", {}),
                    "telemetry": sd.get("telemetry") or GLOBAL_MONITOR.telemetry_snapshot(),
                })

        with st.expander("Diagnostik scan, persistensi database, resource, dan audit keamanan"):
            st.caption("Sumber aktif: " + str(getattr(engine.market, "source_label", "Binance USD-M Futures")) + " · permintaan berasal dari server aplikasi.")
            diagnostic = {
                k: report.get(k)
                for k in (
                    "scan_id", "scan_status", "data_status", "news_status", "trigger",
                    "started_at_ms", "completed_at_ms", "last_scan_at_ms", "next_scan_at_ms",
                    "configured_interval", "effective_interval", "now_ms", "duration_seconds",
                    "universe_loaded", "instrument_kind", "market_provider", "ledger_db",
                    "validation", "market_error", "filter_diagnostics", "stage_timings",
                    "queued_candidates", "queued_candidates_total",
                    "all_deferred_symbols", "all_deferred_total",
                    "database_fingerprint", "provider_failover",
                    "queue_persistence_status", "runtime_diagnostics",
                )
            }
            diagnostic["version"] = APP_VERSION
            active_diag_ledger = engine.ledger_for(active_kind)
            db_diag, health_diag = _cached_db_status(active_diag_ledger)
            diagnostic["persistence"] = db_diag
            diagnostic["worker_heartbeat"] = hb
            diagnostic["worker_health"] = worker_health
            diagnostic["database_health"] = health_diag
            diagnostic["audit_health"] = engine.security.audit_health_status() if hasattr(engine.security, "audit_health_status") else {}
            diagnostic["ledger_db"] = database_display_identity(
                active_diag_ledger.db,
                pg_url=getattr(active_diag_ledger, "pg_url", None),
                get_secret=getattr(active_diag_ledger, "secret_getter", None),
            )
            diagnostic["database_fingerprint"] = database_identity_fingerprint(
                active_diag_ledger.db,
                pg_url=getattr(active_diag_ledger, "pg_url", None),
                get_secret=getattr(active_diag_ledger, "secret_getter", None),
            )
            diagnostic["verified_rw"] = verify_repository_read_write(
                active_diag_ledger.db,
                pg_url=getattr(active_diag_ledger, "pg_url", None),
                get_secret=getattr(active_diag_ledger, "secret_getter", None),
            )
            if hasattr(engine.alerts, "telegram_status"):
                diagnostic["telegram_reliability"] = engine.alerts.telegram_status(getattr(engine, "predictive_store", None))
            try:
                from futures.memory_profiler import profile_scanner_memory
                diagnostic["memory_profile"] = profile_scanner_memory(engine, getattr(engine, "intrabar_stream", None))
            except Exception:
                pass
            diagnostic["resources"] = GLOBAL_MONITOR.snapshot()
            st.json(diagnostic)
            audit_rows = engine.security.audit_entries(limit=20)
            if audit_rows:
                st.dataframe(pd.DataFrame(audit_rows), hide_index=True, use_container_width=True)
            st.caption("Pada mesin yang menjalankan aplikasi, gunakan: python check_market_access.py. "
                       "Uji ini tidak memanggil AI, mengubah jurnal, atau mengirim Telegram.")
        if report.get("shortlist"):
            st.markdown("**Tahap 1 — Shortlist Seluruh Market (LONG & SHORT Watchlist)**")
            st.dataframe(pd.DataFrame(report["shortlist"]).rename(columns={"symbol": "Pair", "quote_volume": "Volume 24h (USDT)",
                "spread_bps": "Spread bps", "liquidity_score": "Skor likuiditas", "watchlist_side": "Watchlist"}), hide_index=True, use_container_width=True)
        if report.get("selected"):
            st.markdown("**Tahap 2 & 3 — Kandidat Terpilih untuk Analisis Mendalam**")
            sel_df = pd.DataFrame(report["selected"])
            cols_to_show = [c for c in ["symbol", "candidate_direction", "m15_regime", "strategy_id", "m15_score", "category", "screening_score", "activity", "momentum_atr_proxy"] if c in sel_df.columns]
            st.dataframe(sel_df[cols_to_show], hide_index=True, use_container_width=True)
        st.caption("Skor adalah kualitas setup teknikal berdasarkan aturan Multi-Stage Scanner (0–100), bukan jaminan probabilitas profit atau win rate.")
        if report.get("worker_analyses"):
            st.dataframe(pd.DataFrame(report["worker_analyses"]), hide_index=True, use_container_width=True)
        for i, data in enumerate(report.get("analyses", [])):
            r, snap = data["result"], data["snapshot"]
            side = {"LONG": "BUY/LONG", "SHORT": "SELL/SHORT"}.get(r.direction, "WAIT")
            conf = r.metrics.get("confidence_score") or (data.get("candidate_info") or {}).get("m15_score", "-")
            stage_status = data.get("stage_status", data["status"])
            kind_badge = "SPOT REFERENCE (Non-Perpetual)" if snap.instrument_kind == "SPOT_REFERENCE" else f"PERPETUAL ({snap.instrument_kind})"
            st.markdown(f"**[SIMULASI PAPER · {kind_badge}] {snap.symbol} · {LABELS[snap.mode]} · {side} · {data['status']} ({stage_status}) · Score/Conf: {conf}/100**")
            _dt = data.get("decision_transparency") or {}
            if _dt:
                st.caption(
                    f"Setup Quality Score: {_dt.get('setup_quality_score', conf)}/100 (bukan probabilitas profit) · "
                    f"M5 Trigger: {_dt.get('m5_trigger_status', '-')} · Regime: {_dt.get('m15_regime', '-')} · "
                    f"Route: {_dt.get('strategy_route', '-')} · Hard Gates Gagal: {', '.join(_dt.get('hard_gates_failed') or []) or 'Tidak ada'} · "
                    f"Keputusan Final: {_dt.get('final_decision', data['status'])}"
                )
            st.write(data.get("paper", ""))
            st.caption(data.get("telegram", ""))
            ai = data.get("ai") or {}
            for reason in (r.reasons + ai.get("reasons", []))[:5]:
                st.write("• " + reason)
            with st.expander(f"Perbandingan mode dan indikator — {snap.symbol}"):
                st.dataframe(pd.DataFrame(r.meta.get("mode_comparison", [])), hide_index=True, use_container_width=True)
                st.dataframe(pd.DataFrame(r.checks), hide_index=True, use_container_width=True)
                if r.plan:
                    p = r.plan
                    st.dataframe(pd.DataFrame([{
                        "KATEGORI": p.get("market_category_label", snap.instrument_kind),
                        "SYMBOL": p["symbol"],
                        "DIRECTION": p["direction"],
                        "CONFIDENCE": f"{p.get('confidence_score', 90)}/100 ({p.get('confidence_calibration_status', 'UNCALIBRATED')})",
                        "MAX LEVERAGE": f"{p.get('max_allowed_leverage', p['leverage'])}x",
                        "SELECTED LEVERAGE (SIMULASI)": f"{p['leverage']}x",
                        "Trigger": p["entry_trigger"],
                        "ENTRY PRICE": p["entry"],
                        "TECHNICAL SL": p["sl"],
                        "SL DISTANCE": f"{p['distance']:.6g} ({p.get('sl_distance_pct', 0):.2f}%)",
                        "EST. MARGIN LOSS": f"{p.get('estimated_margin_loss_pct', 0):.2f}%",
                        "ACCOUNT RISK": f"{p['risk']:.2f} USDT",
                        "INITIAL MARGIN": f"{p['margin']:.2f} USDT",
                        "NOTIONAL": f"{p['notional']:.2f} USDT",
                        "STRATEGY": f"{p.get('strategy', 'F')} ({p.get('strategy_name', 'Hybrid Adaptive')})",
                        "M15 REGIME": p.get("m15_regime", "-"),
                        "TP1 (+1R 40%)": p["tp1"],
                        "TP2 (+2R 35%)": p["tp2"],
                        "TP3 (+3R 25%)": p.get("tp3", "-"),
                        "EST. FEES": f"{p.get('estimated_fees_usdt', 0):.4f} USDT",
                        "NET RR TP1": f"{p['net_rr_tp1']:.2f}",
                        "Berlaku sampai": stamp(p["expires_ms"]),
                    }]), hide_index=True, use_container_width=True)
                if st.checkbox("Tampilkan grafik kandidat", key=f"chart_{snap.symbol}_{snap.mode}"):
                    from manual_app import draw_chart
                    draw_chart(snap, r.plan)
            st.download_button("Unduh analisis " + snap.symbol, json.dumps({"baseline": asdict(r), "ai": ai, "status": data["status"]}, ensure_ascii=False, indent=2),
                               f"{snap.symbol}_{snap.mode}_paper_analysis.json", "application/json", key=f"report_{i}")
    with paper_tab:
        paper_table(engine, report.get("now_ms") or int(time.time() * 1000))
    with history_tab:
        active_kind = getattr(engine.market, "instrument_kind", "USD_M_PERPETUAL")
        records = history.load(engine.ledger_for(active_kind).db)
        if records:
            st.dataframe(pd.DataFrame([{"Waktu": stamp(x["baseline"]["meta"]["time_ms"]), "Pair": x["baseline"]["meta"]["symbol"],
                "Instrumen": x["baseline"]["meta"].get("instrument_kind", "USD_M_PERPETUAL"),
                "Mode": x["baseline"]["meta"]["mode"], "Status": x["final_status"], "Scope": x["baseline"]["meta"].get("scope", "MANUAL")} for x in records]), hide_index=True)
        else:
            st.info("Belum ada analisis kandidat tersimpan.")
    with rules_tab:
        st.markdown("**PRINSIP UTAMA:** `SCREEN ALL MARKETS → FILTER → RANK → SELECT TOP 1–2 → DEEP ANALYSIS → M5 CONFIRMATION → RISK VALIDATION → TELEGRAM ALERT`")
        st.markdown("**SCALPER:** bias 15M / eksekusi 5M · **INTRADAY:** 4H / 15M · **SWING:** 1D / 4H.")
        st.write("Seluruh keputusan pengelolaan posisi menggunakan spesifikasi **Hybrid Adaptive Strategy F v1.0**: Regime M15 (`detect_m15_regime`), Routing Strategi `A`–`E` pada M5, perhitungan TP (`TP1=+1R 40%`, `TP2=+2R 35%`, `TP3=+3R Runner 25%` dengan fallback lot otomatis `60/40` dan `100%`), net break-even setelah TP1, trailing `+1,5R` (`1,25 ATR M5`), time exit `6` dan `12` bar M5, masa berlaku order `2` candle M5, serta Groq sebagai **Contextual Advisor (Advisor-Only)**.")
        st.write("Jurnal **Spot Reference** (`spot_paper_history.sqlite3`), **Bybit Perpetual** (`bybit_paper_history.sqlite3`), dan **Binance USD-M Futures** (`paper_history.sqlite3`) dipisahkan secara ketat. Spot Reference bukan Futures Perpetual: harga spot tidak identik dengan Mark Price Futures, funding dan leverage hanya asumsi simulasi, dan perhitungan PnL tidak disamakan dengan kontrak perpetual.")
        st.download_button("Unduh masterprompt lengkap", (ROOT / "STRATEGY_RULES.txt").read_text(), "STRATEGY_RULES.txt", "text/plain")


def main():
    st.set_page_config(page_title=f"Futures Desk · v{APP_VERSION}", page_icon="📡", layout="wide")
    st.markdown("<style>.block-container{max-width:1280px;padding-top:2rem}[data-testid=stMetric]{border:1px solid #e4e8ef;border-radius:12px;padding:12px}</style>", unsafe_allow_html=True)
    st.caption(f"FUTURES DESK / {APP_VERSION} / MULTI-LEDGER & SERVER-SIDE RBAC / PAPER SIMULATION ONLY")
    st.title("Market scanner otomatis")
    st.caption("Tanpa input pair · multi-stage screening · isolasi database per provider · otorisasi server-side · interval 1m / 5m / 15m")
    st.info("SCANNER SPOT / MULTI-PROVIDER (SIMULASI PAPER): Tidak mengirim order ke bursa nyata. Jika Binance Futures (HTTP 451) dan Bybit (HTTP 403) diblokir oleh lokasi server hosting, aplikasi otomatis beralih ke Binance Spot Reference (https://data-api.binance.vision) dengan database jurnal terpisah.")
    try:
        engine, config, auto = configuration()
    except DatabaseConfigurationError as db_exc:
        st.error(f"⚠️ KONFIGURASI DATABASE POSTGRESQL GAGAL: {db_exc}")
        st.info(
            "Cara memperbaiki DATABASE_URL Supabase di Streamlit Cloud Secrets:\n"
            "1. Di dashboard Supabase, klik tombol **Connect** di bagian atas.\n"
            "2. Pada bagian **Method**, jangan pilih *Direct connection* (`db.xxxx.supabase.co` hanya mendukung IPv6 dan akan gagal di Streamlit Cloud). "
            "Pilih **Transaction pooler** (port `6543`) atau **Session pooler** (port `5432`) yang alamat host-nya berakhiran **`.pooler.supabase.com`**.\n"
            "3. Pastikan tanda kurung siku `[YOUR-PASSWORD]` dihapus seluruhnya (contoh benar: `postgresql://postgres.xxxx:PasswordKamu123@aws-0-ap-southeast-1.pooler.supabase.com:6543/postgres`)."
        )
        return
    # BUG-37: Decouple passive UI refresh (60s) from market scanner interval; never refresh every 15s.
    frag_interval = f"{UI_REFRESH_SECONDS}s" if auto else None
    st.fragment(run_every=frag_interval)(dashboard)(engine, config, auto)


if __name__ == "__main__":
    main()
